-- Combined encounters named differently in the journal.
local function Pair(a, b, joiner)
    local out = {}
    for lang, name in pairs(BOSSES[a] or {}) do
        if BOSSES[b] and BOSSES[b][lang] then out[lang] = name .. joiner .. BOSSES[b][lang] end
    end
    return out
end
BOSSES["Vazruden and Nazan"] = Pair("Vazruden", "Nazan", " & ")

local function Apply()
    FDJ.ContentLocales = FDJ.ContentLocales or {}
    for _, lang in ipairs({ "deDE", "frFR", "esES", "itIT", "ptBR", "ruRU", "koKR", "zhCN", "zhTW" }) do
        local content = FDJ.ContentLocales[lang] or {}
        FDJ.ContentLocales[lang] = content
        content.dungeons = content.dungeons or {}
        content.bosses = content.bosses or {}
        for internal, names in pairs(DUNGEONS) do
            if names[lang] then
                content.dungeons[internal] = content.dungeons[internal] or {}
                content.dungeons[internal].name = names[lang]
            end
        end
        for internal, names in pairs(WING_PREFIX) do
            local entry = content.dungeons[internal]
            local current = entry and entry.name
            local prefix = names[lang]
            if prefix and type(current) == "string" then
                -- Keep the wing part after the separator (":" / " :" / "：" / " - ").
                local wing = current:match("^.-%s*[:：]%s*(.+)$") or current:match("^.-%s+%-%s+(.+)$")
                if wing and wing ~= "" then
                    local sep = (lang == "zhCN" or lang == "zhTW") and "：" or (lang == "frFR" and " : " or ": ")
                    entry.name = prefix .. sep .. wing
                end
            end
        end
        for internal, names in pairs(BOSSES) do
            if names[lang] then content.bosses[internal] = names[lang] end
        end
    end
end
Apply()
local f = CreateFrame and CreateFrame("Frame")
if f then
    f:RegisterEvent("PLAYER_LOGIN")
    f:SetScript("OnEvent", function() pcall(Apply) end)
end
